  "implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    members = {}
    for node, group in refinement.items():
        members.setdefault(group, []).append(node)
    for group in members:
        members[group].sort()
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        key = (gu, gv) if gu <= gv else (gv, gu)
        agg[key] = agg.get(key, 0) + w
    aggregate_edges = sorted([list(k) + [v] for k, v in agg.items()], key=lambda x: (x[0], x[1]))
    return {'aggregate_edges': aggregate_edges, 'members': members}"
}
